import{_ as t,o as r,c as s,ah as n}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Types de documents","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/gestion-documentaire/types-de-documents.md","filePath":"src/guide/gestion-documentaire/types-de-documents.md"}'),o={name:"guide/gestion-documentaire/types-de-documents.md"};function d(i,e,a,l,u,c){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="types-de-documents" tabindex="-1">Types de documents <a class="header-anchor" href="#types-de-documents" aria-label="Permalink to &quot;Types de documents&quot;">​</a></h1><p>Le catalogue des <strong>Types de documents</strong> décrit les documents que l&#39;établissement range : dans quel dossier chacun va, qui le consulte, qui le valide, s&#39;il est confidentiel et combien de temps il est conservé. Il est tenu par un administrateur ou le gestionnaire documentaire, depuis l&#39;espace <strong>Documents</strong> → <strong>Types de documents</strong>.</p><h2 id="le-catalogue-de-depart" tabindex="-1">Le catalogue de départ <a class="header-anchor" href="#le-catalogue-de-depart" aria-label="Permalink to &quot;Le catalogue de départ&quot;">​</a></h2><p>ERA démarre avec la liste habituelle, que vous adaptez librement :</p><table tabindex="0"><thead><tr><th>Type</th><th>Dossier</th><th>Origine</th><th>Consulte et valide</th></tr></thead><tbody><tr><td>Dossier d&#39;inscription</td><td>Élève</td><td>Importé</td><td>Gestionnaire, secrétariat</td></tr><tr><td>Acte de naissance</td><td>Élève</td><td>Importé</td><td>Gestionnaire, secrétariat</td></tr><tr><td>Dossier médical</td><td>Élève</td><td>Importé (confidentiel)</td><td>Infirmerie</td></tr><tr><td>Dossier de candidature</td><td>Élève</td><td>Importé</td><td>Gestionnaire, secrétariat</td></tr><tr><td>Relevé de notes</td><td>Élève</td><td>Produit par l&#39;établissement</td><td>Gestionnaire, secrétariat</td></tr><tr><td>Attestation</td><td>Élève</td><td>Produit par l&#39;établissement</td><td>Gestionnaire, secrétariat</td></tr><tr><td>Diplôme</td><td>Élève</td><td>Produit par l&#39;établissement</td><td>Gestionnaire, secrétariat</td></tr><tr><td>Convention de stage</td><td>Élève</td><td>Produit par l&#39;établissement</td><td>Gestionnaire, secrétariat</td></tr><tr><td>Facture ou reçu</td><td>Élève</td><td>Produit par l&#39;établissement</td><td>Gestionnaire, secrétariat ; la caisse consulte</td></tr><tr><td>Contrat de travail</td><td>Employé</td><td>Importé (confidentiel)</td><td>Gestionnaire</td></tr><tr><td>Procès-verbal</td><td>Établissement</td><td>Produit par l&#39;établissement</td><td>Gestionnaire, secrétariat</td></tr></tbody></table><p>Un administrateur consulte et valide toujours tous les types, y compris les confidentiels. Les noms de départ s&#39;affichent dans la langue de chaque utilisateur tant que vous ne les renommez pas.</p><h2 id="creer-ou-modifier-un-type" tabindex="-1">Créer ou modifier un type <a class="header-anchor" href="#creer-ou-modifier-un-type" aria-label="Permalink to &quot;Créer ou modifier un type&quot;">​</a></h2><ol><li>Cliquez sur <strong>Nouveau type</strong>, ou sur <strong>Modifier</strong> sur la ligne d&#39;un type.</li><li>Renseignez le <strong>Nom</strong>.</li><li>Choisissez le <strong>Dossier</strong> : celui de l&#39;élève, de l&#39;employé, ou les documents de l&#39;établissement. Une fois des documents rangés sous un type, son dossier ne peut plus changer.</li><li>Choisissez l&#39;<strong>Origine</strong> : <strong>Importé</strong> pour un document remis par une famille ou un employé, <strong>Produit par l&#39;établissement</strong> pour un document qu&#39;il délivre.</li><li>Indiquez la <strong>Durée de conservation</strong> en années, ou laissez vide pour le conserver sans limite.</li><li>Cochez <strong>Document confidentiel</strong> pour que chaque consultation soit inscrite au journal d&#39;activité.</li><li>Dans <strong>Accès</strong>, cochez pour chaque profil s&#39;il <strong>consulte et dépose</strong> ce type, et s&#39;il le <strong>valide</strong>. Qui valide un type le consulte forcément aussi : la première case se coche d&#39;elle-même.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Réserver un type aux administrateurs</p><p>Pour réserver un type à la direction, ne cochez aucun profil : seuls les administrateurs y auront accès.</p></div><h2 id="supprimer-un-type" tabindex="-1">Supprimer un type <a class="header-anchor" href="#supprimer-un-type" aria-label="Permalink to &quot;Supprimer un type&quot;">​</a></h2><p>Un type sous lequel aucun document n&#39;est rangé peut être supprimé avec <strong>Supprimer</strong>. Dès qu&#39;un document y est rangé, le bouton disparaît : le type reste au catalogue, vous pouvez seulement le renommer ou changer ses accès.</p>',11)])])}const g=t(o,[["render",d]]);export{m as __pageData,g as default};
